vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p);

fragColor = vec4(vec3(d), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

fragColor = vec4(vec3(d), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

vec3 inside = vec3(0.31, 0.84, 1.0);
vec3 outside = vec3(1.0, 0.45, 0.42);
vec3 colour = mix(inside, outside, step(0.0, d));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

float ring = smoothstep(-0.04, -0.02, d) - smoothstep(0.02, 0.04, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), ring);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float radius = 0.3;
float d = length(p) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 centre = vec2(0.2, -0.2);
float radius = 0.3;
float d = length(p - centre) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 centre = vec2(sin(iTime) * 0.24, cos(iTime) * 0.45);
float radius = 0.22 + sin(iTime * 2.0) * 0.06;
float d = length(p - centre) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.26;

float fill = 1.0 - smoothstep(0.0, 0.012, d);
float glow = 1.0 - smoothstep(0.0, 0.5, d);

vec3 colour = vec3(0.05, 0.05, 0.08);
colour = mix(colour, vec3(0.18, 0.42, 0.55), glow);
colour = mix(colour, vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 q = abs(p);

fragColor = vec4(q.x, q.y, 0.25, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 halfSize = vec2(0.34, 0.22);
vec2 q = abs(p) - halfSize;

float d = max(q.x, q.y);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 q = abs(p) - vec2(0.34, 0.22);

float outside = length(max(q, 0.0));

float glow = 1.0 - smoothstep(0.0, 0.35, outside);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), glow);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float rounding = 0.1;
vec2 q = abs(p) - (vec2(0.34, 0.22) - rounding);

float d = length(max(q, 0.0)) - rounding;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float fillA = 1.0 - smoothstep(0.0, 0.012, a);
float fillB = 1.0 - smoothstep(0.0, 0.012, b);

vec3 colour = vec3(0.05, 0.05, 0.08);
colour = mix(colour, vec3(0.31, 0.84, 1.0), fillA);
colour = mix(colour, vec3(1.0, 0.45, 0.42), fillB);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = min(a, b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = max(a, b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = max(a, -b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float rounding = 0.08;
vec2 q = abs(p) - (vec2(0.3, 0.2) - rounding);
float box = length(max(q, 0.0)) - rounding;

float ball = length(p - vec2(0.0, 0.3)) - 0.14;

float d = min(box, ball);

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);
